// IMPROVED: Extract command and route to appropriate handler
const message = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;
const username = $input.first().json.message.from.username || 'Unknown';
const userId = $input.first().json.message.from.id;

// Parse command
const parts = message.split(' ');
const command = parts[0].toLowerCase();

// Route based on command
if (command === '/start5whys') {
  const rcaTicket = parts[1] || 'RCA-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.floor(Math.random() * 1000);
  const sessionId = '5WHY-' + Date.now();

  return [{
    json: {
      action: 'START_NEW',
      sessionId: sessionId,
      rcaTicket: rcaTicket,
      chatId: chatId,
      username: username,
      userId: userId,
      timestamp: new Date().toISOString(),
      status: 'INITIALIZED',
      currentWhyLevel: 0, // 0 means problem statement not yet collected
      problemStatement: '',
      whyData: []
    }
  }];
}
else if (command === '/status') {
  return [{
    json: {
      action: 'CHECK_STATUS',
      chatId: chatId,
      userId: userId
    }
  }];
}
else if (command === '/help') {
  return [{
    json: {
      action: 'SHOW_HELP',
      chatId: chatId
    }
  }];
}
else if (command.startsWith('/ready')) {
  const whyLevel = parseInt(command.replace('/ready', '')) || 0;
  return [{
    json: {
      action: 'DATA_READY',
      whyLevel: whyLevel,
      chatId: chatId,
      userId: userId,
      message: message
    }
  }];
}
else if (command === '/cancel') {
  return [{
    json: {
      action: 'CANCEL_SESSION',
      chatId: chatId,
      userId: userId
    }
  }];
}
else {
  // Unknown command - send help
  return [{
    json: {
      action: 'UNKNOWN_COMMAND',
      chatId: chatId,
      originalMessage: message
    }
  }];
}

// IMPROVED: Create 5 rows with validation status
const sessionId = $input.first().json.sessionId;
const rows = [];

for (let i = 1; i <= 5; i++) {
  rows.push({
    json: {
      sessionId: sessionId,
      whyLevel: i,
      question: '', // Will be generated by Claude
      initialAnswer: '',
      dataGathered: '',
      validatedAnswer: '',
      status: 'Not Started',
      dataQuality: 'Unknown', // NEW: Track data quality
      attemptCount: 0, // NEW: Track how many times user tried
      createdAt: new Date().toISOString(),
      lastModified: ''
    }
  });
}

return rows;

// IMPROVED: Validate problem statement
const sessionId = $node['Route Command'].json.sessionId;
const chatId = $node['Route Command'].json.chatId;
const input = $input.first().json;

// Extract problem statement from webhook
let problemStatement = '';
if (input.body && input.body.message) {
  problemStatement = input.body.message;
} else if (input.body && input.body.text) {
  problemStatement = input.body.text;
} else if (input.message) {
  problemStatement = input.message;
} else {
  problemStatement = JSON.stringify(input);
}

// Validate problem statement
const isValid = problemStatement.length >= 20; // Minimum 20 characters
const hasNumbers = /\d/.test(problemStatement); // Should contain numbers (KPI values)

return [{
  json: {
    sessionId: sessionId,
    chatId: chatId,
    problemStatement: problemStatement,
    isValid: isValid,
    hasNumbers: hasNumbers,
    quality: isValid && hasNumbers ? 'Good' : 'Needs Improvement',
    timestamp: new Date().toISOString()
  }
}];

// IMPROVED: Extract and validate Claude response
const input = $input.first().json;

// Check for error
if (input.error) {
  return [{
    json: {
      error: true,
      errorMessage: input.error.message || 'Unknown error',
      chatId: $node['Initialize Loop Counter'].json.chatId,
      currentWhyLevel: $node['Initialize Loop Counter'].json.currentWhyLevel
    }
  }];
}

// Extract Claude response
const claudeResponse = input.content && input.content[0] ? input.content[0].text : 'Error: No response';

// Validate response has required sections
const hasQuestion = claudeResponse.includes('QUESTION:');
const hasDataToGather = claudeResponse.includes('DATA TO GATHER:');
const hasSpecificChecks = claudeResponse.includes('SPECIFIC CHECKS:');

const isValid = hasQuestion && hasDataToGather && hasSpecificChecks;

return [{
  json: {
    sessionId: $node['Initialize Loop Counter'].json.sessionId,
    chatId: $node['Initialize Loop Counter'].json.chatId,
    currentWhyLevel: $node['Initialize Loop Counter'].json.currentWhyLevel,
    claudeGuidance: claudeResponse,
    isValid: isValid,
    error: !isValid,
    errorMessage: !isValid ? 'Claude response missing required sections' : null,
    timestamp: new Date().toISOString()
  }
}];

// IMPROVED: Handle timeout
const input = $input.first().json;

// Check if this is a timeout (no body)
if (!input.body || Object.keys(input.body).length === 0) {
  return [{
    json: {
      timeout: true,
      sessionId: $node['Initialize Loop Counter'].json.sessionId,
      chatId: $node['Initialize Loop Counter'].json.chatId,
      currentWhyLevel: $node['Initialize Loop Counter'].json.currentWhyLevel,
      message: 'User did not respond within timeout period'
    }
  }];
}

// Normal response
return [{
  json: {
    timeout: false,
    sessionId: $node['Initialize Loop Counter'].json.sessionId,
    chatId: $node['Initialize Loop Counter'].json.chatId,
    currentWhyLevel: $node['Initialize Loop Counter'].json.currentWhyLevel,
    userResponse: input.body.message || input.body.text || 'No message',
    timestamp: new Date().toISOString()
  }
}];

// IMPROVED: Validate data quality
const data = $input.first().json;

// Check if data exists
if (!data || Object.keys(data).length === 0) {
  return [{
    json: {
      isValid: false,
      errorMessage: 'No data found in sheet for this Why level',
      dataQuality: 'Missing',
      needsRetry: true,
      ...data
    }
  }];
}

// Validate required fields
const initialAnswer = data.initialAnswer || '';
const dataGathered = data.dataGathered || '';
const validatedAnswer = data.validatedAnswer || '';

// Quality checks
const hasInitialAnswer = initialAnswer.length >= 10;
const hasDataGathered = dataGathered.length >= 20;
const hasValidatedAnswer = validatedAnswer.length >= 10;
const hasNumbers = /\d/.test(dataGathered); // Data should contain metrics

const isValid = hasInitialAnswer && hasDataGathered && hasValidatedAnswer;
const isHighQuality = isValid && hasNumbers && dataGathered.length >= 50;

let dataQuality = 'Poor';
if (isHighQuality) dataQuality = 'Excellent';
else if (isValid) dataQuality = 'Acceptable';

return [{
  json: {
    ...data,
    isValid: isValid,
    isHighQuality: isHighQuality,
    dataQuality: dataQuality,
    hasInitialAnswer: hasInitialAnswer,
    hasDataGathered: hasDataGathered,
    hasValidatedAnswer: hasValidatedAnswer,
    hasNumbers: hasNumbers,
    needsRetry: !isValid,
    sessionId: $node['Check for Timeout'].json.sessionId,
    chatId: $node['Check for Timeout'].json.chatId,
    currentWhyLevel: $node['Check for Timeout'].json.currentWhyLevel,
    timestamp: new Date().toISOString()
  }
}];

