// IMPROVED: Compile all data with validation
const allWhys = $input.all();
const problemStatement = $node['Validate Problem Statement'].json.problemStatement;
const sessionId = $node['Initialize Loop Counter'].json.sessionId;
const chatId = $node['Initialize Loop Counter'].json.chatId;

// Build comprehensive data structure
const compiledData = {
  sessionId: sessionId,
  chatId: chatId,
  problemStatement: problemStatement,
  whys: [],
  overallQuality: 'Unknown'
};

let qualityScores = [];

for (let i = 0; i < allWhys.length && i < 5; i++) {
  const why = allWhys[i].json;
  compiledData.whys.push({
    level: i + 1,
    question: why.question || '',
    initialAnswer: why.initialAnswer || '',
    dataGathered: why.dataGathered || '',
    validatedAnswer: why.validatedAnswer || '',
    dataQuality: why.dataQuality || 'Unknown'
  });

  // Score quality
  const qualityMap = { 'Excellent': 5, 'Good': 4, 'Acceptable': 3, 'Poor': 2, 'Missing': 1, 'Unknown': 0 };
  qualityScores.push(qualityMap[why.dataQuality] || 0);
}

// Calculate overall quality
const avgScore = qualityScores.reduce((a, b) => a + b, 0) / qualityScores.length;
if (avgScore >= 4.5) compiledData.overallQuality = 'Excellent';
else if (avgScore >= 3.5) compiledData.overallQuality = 'Good';
else if (avgScore >= 2.5) compiledData.overallQuality = 'Acceptable';
else compiledData.overallQuality = 'Needs Improvement';

return [{ json: compiledData }];

// Extract final analysis
const input = $input.first().json;

if (input.error) {
  return [{
    json: {
      error: true,
      errorMessage: input.error.message || 'Failed to generate analysis',
      sessionId: $node['Compile All Data'].json.sessionId,
      chatId: $node['Compile All Data'].json.chatId
    }
  }];
}

const finalAnalysis = input.content && input.content[0] ? input.content[0].text : 'Error: No analysis generated';

return [{
  json: {
    sessionId: $node['Compile All Data'].json.sessionId,
    chatId: $node['Compile All Data'].json.chatId,
    rcaTicket: $node['Route Command'].json.rcaTicket,
    finalAnalysis: finalAnalysis,
    overallQuality: $node['Compile All Data'].json.overallQuality,
    problemStatement: $node['Compile All Data'].json.problemStatement,
    timestamp: new Date().toISOString(),
    status: 'COMPLETED',
    error: false
  }
}];

